    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --surface: #131a2d;
        --surface-strong: #18213a;
        --surface-elevated: #1d2845;
        --border: #33415f;
        --text: #f3f7ff;
        --muted: #a9b4cd;
        --accent: #8b9fff;
        --accent-strong: #a8b5ff;
        --danger: #ff6b7d;
        --danger-strong: #ff8f9c;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
        --radius-lg: 24px;
        --radius-md: 18px;
        --radius-sm: 12px;
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        margin: 0;
        min-height: 100%;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
        background:
          radial-gradient(circle at top, rgba(139, 159, 255, 0.18), transparent 28%),
          linear-gradient(180deg, #0d1222 0%, var(--bg) 100%);
        color: var(--text);
      }

      body {
        display: flex;
        justify-content: center;
        padding: 24px;
      }

      a,
      button {
        font: inherit;
      }

      button {
        cursor: pointer;
      }

      .skip-link {
        position: absolute;
        left: 16px;
        top: 16px;
        transform: translateY(-200%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--text);
        color: #111827;
        text-decoration: none;
        transition: transform 0.2s ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .app-shell {
        width: min(100%, 960px);
      }

      .page-header {
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 16px;
        margin-bottom: 24px;
      }

      .eyebrow {
        margin: 0 0 8px;
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.5rem);
        line-height: 1;
      }

      .page-copy {
        margin: 12px 0 0;
        max-width: 40rem;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      .status {
        min-height: 1.5rem;
        margin-top: 16px;
        color: var(--accent-strong);
        font-size: 0.95rem;
      }

      .preview-card {
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-lg);
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
        box-shadow: var(--shadow);
      }

      .preview-image-wrap {
        padding: 24px;
      }

      .preview-image {
        display: block;
        width: 100%;
        height: auto;
        aspect-ratio: 16 / 10;
        object-fit: cover;
        border-radius: var(--radius-md);
        border: 1px solid rgba(255, 255, 255, 0.08);
        background: #0f172a;
      }

      .preview-meta {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 0 24px 24px;
      }

      .image-title {
        margin: 0;
        font-size: 1.125rem;
      }

      .image-details {
        margin: 6px 0 0;
        color: var(--muted);
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
      }

      .button {
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.9rem 1.15rem;
        color: var(--text);
        transition:
          transform 0.2s ease,
          background 0.2s ease,
          border-color 0.2s ease;
      }

      .button:hover {
        transform: translateY(-1px);
      }

      .button:focus-visible,
      .dialog button:focus-visible {
        outline: 2px solid transparent;
        box-shadow: 0 0 0 3px var(--accent-strong);
      }

      .button-secondary {
        background: rgba(255, 255, 255, 0.05);
        border-color: rgba(255, 255, 255, 0.08);
      }

      .button-danger {
        background: linear-gradient(180deg, var(--danger), #f05468);
      }

      .button-danger:hover {
        background: linear-gradient(180deg, var(--danger-strong), #ff7182);
      }

      .empty-state {
        padding: 56px 24px;
        text-align: center;
        border: 1px dashed rgba(255, 255, 255, 0.16);
        border-radius: var(--radius-lg);
        background: rgba(255, 255, 255, 0.03);
      }

      .empty-state h2 {
        margin-top: 0;
        margin-bottom: 12px;
      }

      .empty-state p {
        margin: 0;
        color: var(--muted);
      }

      dialog {
        padding: 0;
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-radius: 22px;
        max-width: min(92vw, 460px);
        width: 100%;
        background: linear-gradient(180deg, var(--surface-strong), var(--surface));
        color: var(--text);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(5, 10, 20, 0.72);
        backdrop-filter: blur(10px);
      }

      .dialog {
        padding: 28px;
      }

      .dialog h2 {
        margin: 0 0 12px;
        font-size: 1.4rem;
      }

      .dialog p {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        flex-wrap: wrap;
        gap: 12px;
        margin-top: 24px;
      }

      @media (max-width: 640px) {
        body {
          padding: 16px;
        }

        .page-header,
        .preview-meta {
          display: block;
        }

        .actions {
          margin-top: 18px;
        }

        .dialog-actions {
          justify-content: stretch;
        }

        .dialog-actions .button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-strong: Canvas;
          --surface-elevated: Canvas;
          --border: ButtonBorder;
          --text: CanvasText;
          --muted: CanvasText;
          --accent: Highlight;
          --accent-strong: Highlight;
          --danger: ButtonFace;
          --danger-strong: ButtonFace;
          --shadow: none;
        }

        .preview-card,
        .preview-image,
        dialog,
        .empty-state,
        .button {
          border: 1px solid ButtonBorder;
        }

        .button,
        .skip-link {
          color: ButtonText;
          background: ButtonFace;
        }

        .button:focus-visible,
        .dialog button:focus-visible {
          box-shadow: none;
          outline: 2px solid Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>
    <script>
      const state = {
        imageDeleted: false,
        statusMessage: "",
      };

      const imageSrc =
        "data:image/svg+xml;utf8," +
        encodeURIComponent(`
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1000" role="img" aria-label="Aurora landscape">
            <defs>
              <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0%" stop-color="#15203d" />
                <stop offset="45%" stop-color="#1c3f7a" />
                <stop offset="100%" stop-color="#0a1327" />
              </linearGradient>
              <linearGradient id="glow" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stop-color="#8b9fff" stop-opacity="0.15" />
                <stop offset="50%" stop-color="#7ef0cf" stop-opacity="0.85" />
                <stop offset="100%" stop-color="#d8e2ff" stop-opacity="0.1" />
              </linearGradient>
            </defs>
            <rect width="1600" height="1000" fill="url(#bg)" />
            <circle cx="1240" cy="200" r="74" fill="#eef4ff" opacity="0.88" />
            <path d="M0 740 C240 640 370 610 600 710 C790 790 960 810 1170 710 C1325 636 1455 620 1600 690 L1600 1000 L0 1000 Z" fill="#111a2f" />
            <path d="M0 790 C180 730 390 760 580 830 C810 915 1030 905 1260 820 C1400 770 1490 768 1600 810 L1600 1000 L0 1000 Z" fill="#09101f" />
            <path d="M160 280 C320 210 450 210 620 280 C790 350 980 355 1120 300 C1280 236 1420 250 1540 310" fill="none" stroke="url(#glow)" stroke-width="74" stroke-linecap="round" opacity="0.95" />
          </svg>
        `);

      function App() {
        return `
          <div class="app-shell">
            ${PageHeader()}
            <main id="main-content" tabindex="-1">
              ${state.imageDeleted ? EmptyState() : ImagePreviewCard()}
            </main>
            ${ConfirmDeleteDialog()}
          </div>
        `;
      }

      function PageHeader() {
        return `
          <header class="page-header">
            <div>
              <p class="eyebrow">Library preview</p>
              <h1>Image preview</h1>
              <p class="page-copy">
                Review a saved image before deciding whether to keep it in your personal library.
              </p>
              <div class="status" aria-live="polite">${escapeHtml(state.statusMessage)}</div>
            </div>
          </header>
        `;
      }

      function ImagePreviewCard() {
        return `
          <section class="preview-card" aria-labelledby="image-title">
            <div class="preview-image-wrap">
              <img
                class="preview-image"
                src="${imageSrc}"
                alt="Aurora bands glowing over a dark mountain ridge"
                width="1600"
                height="1000"
              />
            </div>
            <div class="preview-meta">
              <div>
                <h2 class="image-title" id="image-title">Northern Lights</h2>
                <p class="image-details">Saved to Landscapes · 6.2 MB · PNG</p>
              </div>
              <div class="actions">
                <button type="button" class="button button-secondary">Download</button>
                <button
                  type="button"
                  class="button button-danger trigger"
                  data-open-dialog
                  aria-haspopup="dialog"
                  aria-controls="delete-dialog"
                >
                  Delete image
                </button>
              </div>
            </div>
          </section>
        `;
      }

      function EmptyState() {
        return `
          <section class="empty-state" aria-labelledby="empty-state-title">
            <h2 id="empty-state-title">Image deleted</h2>
            <p>The image has been removed from your library.</p>
          </section>
        `;
      }

      function ConfirmDeleteDialog() {
        return `
          <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
            <div class="dialog">
              <h2 id="dialog-title">Delete image from library?</h2>
              <p id="dialog-description">
                This will remove <strong>Northern Lights</strong> from your library. You can’t undo this action.
              </p>
              <div class="dialog-actions">
                <button type="button" class="button button-secondary" data-close-dialog>
                  Cancel
                </button>
                <button type="button" class="button button-danger" data-confirm-delete>
                  Yes, delete image
                </button>
              </div>
            </div>
          </dialog>
        `;
      }

      function render() {
        document.getElementById("root").innerHTML = App();
        bindEvents();
      }

      function bindEvents() {
        const dialog = document.getElementById("delete-dialog");
        const openButton = document.querySelector("[data-open-dialog]");
        const closeButton = document.querySelector("[data-close-dialog]");
        const confirmButton = document.querySelector("[data-confirm-delete]");

        if (openButton && dialog) {
          openButton.addEventListener("click", () => {
            dialog.showModal();
            closeButton?.focus();
          });
        }

        closeButton?.addEventListener("click", () => {
          dialog.close();
          openButton?.focus();
        });

        dialog?.addEventListener("close", () => {
          if (!state.imageDeleted) {
            openButton?.focus();
          }
        });

        confirmButton?.addEventListener("click", () => {
          state.imageDeleted = true;
          state.statusMessage = "The image was deleted from your library.";
          dialog.close();
          render();
          document.getElementById("main-content")?.focus();
        });
      }

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      render();
    </script>
